import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

function DriverDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [availableDeliveries, setAvailableDeliveries] = useState([]);
  const [activeJobs, setActiveJobs] = useState([]);
  const [history, setHistory] = useState([]);
  const [earnings, setEarnings] = useState({ 
    total: 0, weekly: 0, today: 0, perDelivery: 20, 
    totalDeliveries: 0, pendingPayout: 0 
  });
  const [payoutHistory, setPayoutHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(true);
  const [currentLocation, setCurrentLocation] = useState({ lat: -1.286389, lng: 36.817223, address: 'Nairobi, Kenya' });
  const [selectedJob, setSelectedJob] = useState(null);
  const [showLocationModal, setShowLocationModal] = useState(false);
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [showPayoutModal, setShowPayoutModal] = useState(false);
  const [payoutAmount, setPayoutAmount] = useState('');
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [filterStatus, setFilterStatus] = useState('all');

  const [vehicleInfo, setVehicleInfo] = useState({
    model: user?.vehicleModel || 'Not specified',
    color: user?.vehicleColor || '',
    plate: user?.vehiclePlate || 'N/A',
    year: user?.vehicleYear || ''
  });

  const [driverStats, setDriverStats] = useState({
    rating: 0, totalRatings: 0, acceptanceRate: 0, onTimeRate: 0, totalDistance: 0, totalHours: 0
  });

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchAllData();
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        setCurrentLocation({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
          address: 'Current Location'
        });
        updateDriverLocation(position.coords.latitude, position.coords.longitude);
      });
    }
    const interval = setInterval(fetchAllData, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const dashboardRes = await fetch('http://localhost:5000/api/driver/dashboard', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const dashboardData = await dashboardRes.json();
      if (dashboardData.success) {
        const data = dashboardData.data;
        setAvailableDeliveries(data.deliveries?.available || []);
        setActiveJobs(data.deliveries?.active || []);
        setHistory(data.deliveries?.history || []);
        setEarnings(data.earnings || { total: 0, weekly: 0, today: 0, perDelivery: 20, totalDeliveries: 0, pendingPayout: 0 });
        setDriverStats(data.stats || {});
        setIsOnline(data.isOnline || false);
        if (data.currentLocation) setCurrentLocation(data.currentLocation);
      }

      const payoutRes = await fetch('http://localhost:5000/api/driver/payout-history', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const payoutData = await payoutRes.json();
      if (payoutData.success) setPayoutHistory(payoutData.payouts || []);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const updateDriverLocation = async (lat, lng) => {
    try {
      await fetch('http://localhost:5000/api/driver/location', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ lat, lng, address: currentLocation.address })
      });
    } catch (error) {
      console.error('Error updating location:', error);
    }
  };

  const updateDriverStatus = async (online) => {
    try {
      const res = await fetch('http://localhost:5000/api/driver/status', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ isOnline: online })
      });
      const data = await res.json();
      if (data.success) {
        setIsOnline(online);
        toast.success(online ? 'You are now online!' : 'You are now offline');
      }
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const acceptDelivery = async (deliveryId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/driver/accept/${deliveryId}`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Delivery accepted!');
        fetchAllData();
      } else {
        toast.error(data.error || 'Failed to accept');
      }
    } catch (error) {
      toast.error('Error accepting delivery');
    }
  };

  const updateDeliveryStatus = async (deliveryId, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/driver/delivery/${deliveryId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Delivery marked as ${status}!`);
        fetchAllData();
        setSelectedJob(null);
      } else {
        toast.error('Failed to update status');
      }
    } catch (error) {
      toast.error('Error updating status');
    }
  };

  const updateVehicleInfo = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/driver/vehicle', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(vehicleInfo)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Vehicle info updated!');
        setShowVehicleModal(false);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to update vehicle');
    }
  };

  const requestPayout = async () => {
    if (!payoutAmount || parseFloat(payoutAmount) <= 0) {
      toast.error('Please enter a valid amount');
      return;
    }
    if (parseFloat(payoutAmount) > earnings.pendingPayout) {
      toast.error('Amount exceeds available balance');
      return;
    }

    try {
      const res = await fetch('http://localhost:5000/api/driver/payout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ amount: parseFloat(payoutAmount) })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(data.message);
        setShowPayoutModal(false);
        setPayoutAmount('');
        fetchAllData();
      } else {
        toast.error(data.error);
      }
    } catch (error) {
      toast.error('Failed to request payout');
    }
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b', confirmed: '#10b981', 'in-progress': '#3b82f6',
      completed: '#8b5cf6', cancelled: '#ef4444', 'driver-assigned': '#8b5cf6',
      pickup: '#3b82f6', 'en-route': '#10b981'
    };
    const labels = {
      pending: '⏳ Pending', confirmed: '✓ Confirmed', 'in-progress': '🔧 In Progress',
      completed: '✅ Completed', cancelled: '❌ Cancelled', 'driver-assigned': '🚗 Assigned',
      pickup: '📍 Pickup', 'en-route': '🚚 En Route'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const getDistanceText = () => {
    const distances = ['0.5 miles away', '1.2 miles away', '0.8 miles away', '1.5 miles away'];
    return distances[Math.floor(Math.random() * distances.length)];
  };

  const getEtaText = () => {
    const etas = ['5-10 min', '10-15 min', '8-12 min', '12-18 min'];
    return etas[Math.floor(Math.random() * etas.length)];
  };

  const filteredHistory = filterStatus === 'all' ? history : history.filter(h => h.status === filterStatus);
  const todayEarnings = earnings.today || 0;
  const todayCompleted = history.filter(d => {
    const today = new Date();
    const deliveryDate = new Date(d.completedAt || d.createdAt);
    return d.status === 'completed' && 
      deliveryDate.getDate() === today.getDate() &&
      deliveryDate.getMonth() === today.getMonth() &&
      deliveryDate.getFullYear() === today.getFullYear();
  }).length;

  const todayHours = todayCompleted * 0.75;
  const todayDistance = todayCompleted * 8;

  return (
    <div style={styles.dashboard}>
      <ToastContainer position="top-right" />

      {/* Header */}
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🚗💨</span>
          <div>
            <h1 style={styles.logoText}>Car Care Connect - Driver</h1>
            <div style={styles.headerSubtitle}>{user?.firstName} {user?.lastName} · ⭐ {driverStats.rating} · 📍 {currentLocation.address.split(',')[0]}</div>
          </div>
        </div>
        <div style={styles.headerRight}>
          <button style={{ ...styles.onlineToggle, backgroundColor: isOnline ? '#10b981' : '#ef4444' }} onClick={() => updateDriverStatus(!isOnline)}>
            <span style={styles.onlineDot}></span>{isOnline ? 'Online' : 'Offline'}
          </button>
          <button style={styles.locationBtn} onClick={() => setShowLocationModal(true)}>📍</button>
          <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>🔔{unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}</div>
          <div style={styles.userInfo}>
            <img src={`https://ui-avatars.com/api/?background=2563eb&color=fff&name=${user?.firstName}`} alt="avatar" style={styles.avatar} />
            <button onClick={onLogout} style={styles.logoutButton}>🚪</button>
          </div>
        </div>
      </div>

      {/* Stats Cards with REAL Earnings */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}><h3>💰 Today</h3><p style={styles.statNumber}>${todayEarnings}</p></div>
        <div style={styles.statCard}><h3>📊 Weekly</h3><p style={styles.statNumber}>${earnings.weekly}</p></div>
        <div style={styles.statCard}><h3>🏆 Total</h3><p style={styles.statNumber}>${earnings.total}</p></div>
        <div style={styles.statCard}><h3>📦 Deliveries</h3><p style={styles.statNumber}>{earnings.totalDeliveries}</p></div>
        <div style={styles.statCard}><h3>⭐ Rating</h3><p style={styles.statNumber}>{driverStats.rating}</p></div>
        <div style={styles.statCard}><h3>💰 Pending</h3><p style={styles.statNumber}>${earnings.pendingPayout}<button style={styles.payoutBtn} onClick={() => setShowPayoutModal(true)}>Request</button></p></div>
      </div>

      {/* Quick Stats */}
      <div style={styles.quickStats}>
        <div style={styles.quickStat}><span>🚗</span> Online: {isOnline ? 'Yes' : 'No'}</div>
        <div style={styles.quickStat}><span>📦</span> Available: {availableDeliveries.length}</div>
        <div style={styles.quickStat}><span>🚚</span> Active: {activeJobs.length}</div>
        <div style={styles.quickStat}><span>⏱️</span> Hours: {driverStats.totalHours}h</div>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'available' ? styles.activeTab : {})}} onClick={() => setActiveTab('available')}>📦 Available ({availableDeliveries.length})</button>
        <button style={{...styles.tab, ...(activeTab === 'active' ? styles.activeTab : {})}} onClick={() => setActiveTab('active')}>🚗 Active ({activeJobs.length})</button>
        <button style={{...styles.tab, ...(activeTab === 'history' ? styles.activeTab : {})}} onClick={() => setActiveTab('history')}>📋 History</button>
        <button style={{...styles.tab, ...(activeTab === 'earnings' ? styles.activeTab : {})}} onClick={() => setActiveTab('earnings')}>💰 Earnings</button>
        <button style={{...styles.tab, ...(activeTab === 'vehicle' ? styles.activeTab : {})}} onClick={() => setActiveTab('vehicle')}>🚗 Vehicle</button>
        <button style={{...styles.tab, ...(activeTab === 'profile' ? styles.activeTab : {})}} onClick={() => setActiveTab('profile')}>👤 Profile</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading...</div> : (
          <>
            {/* Dashboard Tab */}
            {activeTab === 'dashboard' && (
              <div style={styles.twoColumn}>
                <div>
                  <div style={styles.card}><h3>📊 Today's Performance</h3>
                    <div style={styles.performanceItem}><span>Deliveries Completed:</span><span style={styles.performanceValue}>{todayCompleted}</span></div>
                    <div style={styles.performanceItem}><span>Hours Worked:</span><span style={styles.performanceValue}>{todayHours.toFixed(1)}h</span></div>
                    <div style={styles.performanceItem}><span>Distance Covered:</span><span style={styles.performanceValue}>{todayDistance} miles</span></div>
                    <div style={styles.performanceItem}><span>Rating Received:</span><span style={styles.performanceValue}>⭐ {driverStats.rating}</span></div>
                  </div>
                  <div style={styles.card}><h3>📍 Current Location</h3>
                    <div style={styles.locationInfo}><span>📌 {currentLocation.address}</span><button style={styles.updateLocationBtn} onClick={() => setShowLocationModal(true)}>Update</button></div>
                    <div style={styles.mapPlaceholder}>🗺️ Map View - Live tracking active</div>
                  </div>
                </div>
                <div>
                  <div style={styles.card}><h3>📈 Performance Stats</h3>
                    <div style={styles.metricItem}><span>Acceptance Rate:</span><div style={styles.progressBar}><div style={{ ...styles.progressFill, width: `${driverStats.acceptanceRate || 0}%`, backgroundColor: '#10b981' }}></div></div><span>{driverStats.acceptanceRate || 0}%</span></div>
                    <div style={styles.metricItem}><span>On-Time Rate:</span><div style={styles.progressBar}><div style={{ ...styles.progressFill, width: `${driverStats.onTimeRate || 0}%`, backgroundColor: '#3b82f6' }}></div></div><span>{driverStats.onTimeRate || 0}%</span></div>
                    <div style={styles.metricItem}><span>Customer Rating:</span><div style={styles.progressBar}><div style={{ ...styles.progressFill, width: `${(driverStats.rating / 5) * 100 || 0}%`, backgroundColor: '#f59e0b' }}></div></div><span>⭐ {driverStats.rating || 0}</span></div>
                  </div>
                  <div style={styles.card}><h3>🚗 Active Jobs ({activeJobs.length})</h3>
                    {activeJobs.length === 0 ? <p>No active jobs</p> : activeJobs.map(job => (
                      <div key={job._id} style={styles.activeJobItem}><div><strong>{job.serviceName}</strong></div><div>Customer: {job.customerId?.firstName}</div><span style={getStatusBadge(job.status)}>{job.status}</span></div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Available Deliveries Tab */}
            {activeTab === 'available' && (
              <div>
                <div style={styles.sectionHeader}><h2>📦 Available Deliveries ({availableDeliveries.length})</h2><span style={styles.onlineBadge}>🟢 You are {isOnline ? 'Online' : 'Offline'}</span></div>
                {availableDeliveries.length === 0 ? (
                  <div style={styles.emptyState}><span style={styles.emptyIcon}>📦</span><h3>No Available Deliveries</h3><p>Check back soon for new concierge requests</p></div>
                ) : (
                  availableDeliveries.map(delivery => (
                    <div key={delivery._id} style={styles.deliveryCard}>
                      <div style={styles.deliveryHeader}><span style={styles.deliveryType}>🚗 Concierge Pickup</span><span style={getStatusBadge(delivery.status)}>{delivery.status}</span></div>
                      <div style={styles.deliveryContent}>
                        <div style={styles.pickupInfo}><span style={styles.infoIcon}>📍</span><div><strong>Pickup Location:</strong><p>{delivery.pickupAddress || delivery.customerId?.address || 'Customer address'}</p><span style={styles.distanceBadge}>{getDistanceText()}</span></div></div>
                        <div style={styles.arrowIcon}>↓</div>
                        <div style={styles.shopInfo}><span style={styles.infoIcon}>🔧</span><div><strong>Service Center:</strong><p>{delivery.providerId?.businessName || 'Auto Service Center'}</p><p>Service: {delivery.serviceName}</p></div></div>
                      </div>
                      <div style={styles.deliveryFooter}><div><span style={styles.etaBadge}>⏱️ ETA: {getEtaText()}</span><span style={styles.priceBadge}>💰 ${earnings.perDelivery}</span></div><button style={styles.acceptBtn} onClick={() => acceptDelivery(delivery._id)}>Accept Delivery →</button></div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Active Jobs Tab */}
            {activeTab === 'active' && (
              <div><h2>🚗 Active Jobs ({activeJobs.length})</h2>
                {activeJobs.length === 0 ? <div style={styles.emptyState}><span style={styles.emptyIcon}>🚗</span><h3>No Active Jobs</h3><p>Accept a delivery to get started</p></div> : activeJobs.map(job => (
                  <div key={job._id} style={styles.activeCard}>
                    <div style={styles.activeHeader}><span style={styles.activeType}>🚗 Active Delivery</span><span style={getStatusBadge(job.status)}>{job.status}</span></div>
                    <div style={styles.progressSteps}>
                      <div style={{...styles.step, ...(job.status === 'confirmed' ? styles.stepActive : styles.stepCompleted)}}><span>1</span> Pickup</div><div style={styles.stepLine}></div>
                      <div style={{...styles.step, ...(job.status === 'in-progress' ? styles.stepActive : job.status === 'confirmed' ? {} : styles.stepCompleted)}}><span>2</span> Drop-off</div><div style={styles.stepLine}></div>
                      <div style={{...styles.step, ...(job.status === 'completed' ? styles.stepActive : {})}}><span>3</span> Complete</div>
                    </div>
                    <div style={styles.jobDetails}>
                      <p><strong>Customer:</strong> {job.customerId?.firstName} {job.customerId?.lastName}</p><p><strong>Phone:</strong> {job.customerId?.phone || 'N/A'}</p>
                      <p><strong>Service:</strong> {job.serviceName}</p><p><strong>Shop:</strong> {job.providerId?.businessName}</p><p><strong>Pickup:</strong> {job.pickupAddress || 'Customer address'}</p>
                    </div>
                    <div style={styles.actionButtons}>
                      {job.status === 'confirmed' && <button style={styles.pickupBtn} onClick={() => updateDeliveryStatus(job._id, 'in-progress')}>📍 Confirm Pickup</button>}
                      {job.status === 'in-progress' && <button style={styles.completeBtn} onClick={() => updateDeliveryStatus(job._id, 'completed')}>✅ Complete Delivery</button>}
                      <button style={styles.contactBtn}>📞 Contact Customer</button>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* History Tab */}
            {activeTab === 'history' && (
              <div><div style={styles.historyHeader}><h2>📋 Delivery History</h2><select style={styles.filterSelect} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}><option value="all">All</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div>
                {filteredHistory.length === 0 ? <div style={styles.emptyState}>No deliveries yet</div> : filteredHistory.map(delivery => (
                  <div key={delivery._id} style={styles.historyCard}><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div><p><strong>{delivery.serviceName}</strong></p><p>Customer: {delivery.customerId?.firstName} {delivery.customerId?.lastName}</p><p>📅 {new Date(delivery.bookingDate).toLocaleDateString()}</p></div>
                    <div style={{ textAlign: 'right' }}><span style={getStatusBadge(delivery.status)}>{delivery.status}</span><p style={styles.earningText}>+${earnings.perDelivery}</p></div>
                  </div></div>
                ))}
              </div>
            )}

            {/* Earnings Tab - COMPLETE */}
            {activeTab === 'earnings' && (
              <div>
                <div style={styles.earningsHeader}><h2>💰 Earnings & Payouts</h2><button style={styles.payoutRequestBtn} onClick={() => setShowPayoutModal(true)}>Request Payout</button></div>

                <div style={styles.earningsGrid}>
                  <div style={styles.earningsCard}><span style={styles.earningsIcon}>💰</span><h3>Total Earnings</h3><p style={styles.earningsAmount}>${earnings.total}</p></div>
                  <div style={styles.earningsCard}><span style={styles.earningsIcon}>📊</span><h3>This Week</h3><p style={styles.earningsAmount}>${earnings.weekly}</p></div>
                  <div style={styles.earningsCard}><span style={styles.earningsIcon}>📦</span><h3>Today</h3><p style={styles.earningsAmount}>${earnings.today}</p></div>
                  <div style={styles.earningsCard}><span style={styles.earningsIcon}>🚗</span><h3>Total Deliveries</h3><p style={styles.earningsAmount}>{earnings.totalDeliveries}</p></div>
                </div>

                <div style={styles.card}>
                  <h3>💸 Pending Payout: <span style={{ color: '#f59e0b' }}>${earnings.pendingPayout}</span></h3>
                  <button style={styles.payoutBtnLarge} onClick={() => setShowPayoutModal(true)}>Request Payout Now</button>
                </div>

                <div style={styles.card}>
                  <h3>📋 Payout History</h3>
                  {payoutHistory.length === 0 ? <p>No payout history yet</p> : payoutHistory.map(p => (
                    <div key={p._id} style={styles.payoutItem}>
                      <span>{p._id}</span>
                      <span>${p.amount.toLocaleString()}</span>
                      <span>{p.count} deliveries</span>
                    </div>
                  ))}
                </div>

                <div style={styles.infoCard}>
                  <h3>💡 How It Works</h3>
                  <ul style={styles.infoList}>
                    <li>💰 <strong>${earnings.perDelivery}</strong> per delivery + customer tips</li>
                    <li>🕐 Average delivery time: 30-45 minutes</li>
                    <li>📊 Payments accumulated and available for payout</li>
                    <li>⭐ Maintain 4.5+ rating for bonus opportunities</li>
                    <li>💸 Payouts processed within 3-5 business days</li>
                  </ul>
                </div>
              </div>
            )}

            {/* Vehicle Tab */}
            {activeTab === 'vehicle' && (
              <div style={styles.vehicleContainer}>
                <div style={styles.vehicleHeader}><h2>🚗 My Vehicle</h2><button style={styles.editBtn} onClick={() => setShowVehicleModal(true)}>✏️ Edit</button></div>
                <div style={styles.vehicleCard}><div style={styles.vehicleIcon}>🚗</div><div style={styles.vehicleDetails}><h3>{vehicleInfo.year} {vehicleInfo.model}</h3><p>Color: {vehicleInfo.color}</p><p>License Plate: {vehicleInfo.plate}</p></div></div>
                <div style={styles.card}><h3>📋 Vehicle Documents</h3><div style={styles.documentItem}><span>Insurance Certificate</span><span style={styles.verifiedBadge}>✅ Verified</span></div><div style={styles.documentItem}><span>Vehicle Registration</span><span style={styles.pendingBadge}>⏳ Pending</span></div></div>
              </div>
            )}

            {/* Profile Tab */}
            {activeTab === 'profile' && (
              <div style={styles.profileContainer}>
                <div style={styles.profileHeader}>
                  <img src={`https://ui-avatars.com/api/?background=2563eb&color=fff&name=${user?.firstName} ${user?.lastName}&size=100`} alt="avatar" style={styles.profileAvatar} />
                  <div><h2>{user?.firstName} {user?.lastName}</h2><p>⭐ {driverStats.rating} • {driverStats.totalRatings} reviews</p><p>Member since {new Date(user?.createdAt || Date.now()).toLocaleDateString()}</p></div>
                </div>
                <div style={styles.profileInfo}>
                  <div><strong>📧 Email:</strong> {user?.email}</div><div><strong>📞 Phone:</strong> {user?.phone}</div>
                  <div><strong>🚗 Driver's License:</strong> {user?.driversLicense || 'N/A'}</div><div><strong>📦 Total Deliveries:</strong> {earnings.totalDeliveries}</div>
                  <div><strong>✅ Acceptance Rate:</strong> {driverStats.acceptanceRate || 0}%</div><div><strong>⏱️ On-Time Rate:</strong> {driverStats.onTimeRate || 0}%</div>
                </div>
                <button style={styles.editProfileBtn}>Edit Profile</button>
              </div>
            )}
          </>
        )}
      </div>

      {/* Modals */}
      {showLocationModal && (
        <div style={styles.modal}><div style={styles.modalContent}><h2>📍 Update Location</h2><div style={styles.mapContainer}><div style={styles.mapPlaceholderLarge}>🗺️ Live Map - Drag to update location</div></div><input style={styles.input} type="text" placeholder="Address" value={currentLocation.address} onChange={(e) => setCurrentLocation({...currentLocation, address: e.target.value})} /><div style={styles.modalActions}><button style={styles.submitBtn} onClick={() => { updateDriverLocation(currentLocation.lat, currentLocation.lng); setShowLocationModal(false); toast.success('Location updated!'); }}>Save Location</button><button style={styles.cancelBtn} onClick={() => setShowLocationModal(false)}>Cancel</button></div></div></div>
      )}

      {showVehicleModal && (
        <div style={styles.modal}><div style={styles.modalContentSmall}><h2>🚗 Update Vehicle Info</h2><form onSubmit={updateVehicleInfo}><input style={styles.input} type="text" placeholder="Vehicle Model" value={vehicleInfo.model} onChange={(e) => setVehicleInfo({...vehicleInfo, model: e.target.value})} required /><input style={styles.input} type="text" placeholder="Color" value={vehicleInfo.color} onChange={(e) => setVehicleInfo({...vehicleInfo, color: e.target.value})} required /><input style={styles.input} type="text" placeholder="License Plate" value={vehicleInfo.plate} onChange={(e) => setVehicleInfo({...vehicleInfo, plate: e.target.value})} required /><input style={styles.input} type="number" placeholder="Year" value={vehicleInfo.year} onChange={(e) => setVehicleInfo({...vehicleInfo, year: e.target.value})} required /><div style={styles.modalActions}><button type="submit" style={styles.submitBtn}>Save</button><button type="button" style={styles.cancelBtn} onClick={() => setShowVehicleModal(false)}>Cancel</button></div></form></div></div>
      )}

      {showPayoutModal && (
        <div style={styles.modal}><div style={styles.modalContentSmall}><h2>💰 Request Payout</h2><p>Available for payout: <strong>${earnings.pendingPayout}</strong></p><p>Per delivery rate: <strong>${earnings.perDelivery}</strong></p><input style={styles.input} type="number" placeholder="Amount" value={payoutAmount} onChange={(e) => setPayoutAmount(e.target.value)} /><div style={styles.modalActions}><button style={styles.submitBtn} onClick={requestPayout}>Request Payout</button><button style={styles.cancelBtn} onClick={() => { setShowPayoutModal(false); setPayoutAmount(''); }}>Cancel</button></div></div></div>
      )}
    </div>
  );
}

